                trade_qty = min(remaining, sell_qty)
                trades.append([id, sell_id, sell_price, trade_qty])
                remaining -= trade_qty
                sell_qty -= trade_qty

                if sell_qty == 0:
                    sell_book.pop(i)
                    if sell_id in order_map:
                        del order_map[sell_id]
                else:
                    sell_book[i] = (sell_price, sell_arr_time, sell_id, sell_qty)
                    order_map[sell_id] = ('sell', sell_price, sell_arr_time, sell_qty)
            else:
                break

            if sell_qty == 0:
                i += 1
            else:
                i += 1

        return remaining

