                side, price, arr_time, qty = order_map[order_id]
                del order_map[order_id]
                if side == 'buy':
                    remove_from_book(order_id, buy_book)
                else:
                    remove_from_book(order_id, sell_book)

        elif order[0] == 'limit':
            order_id = order[1]
            side = order[2]
            price = order[3]
            qty = order[4]

            if side == 'buy':
                remaining = match_buy(order_id, price, qty, False)
